		route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(fixtureValidation())
		});
	});

	await page.route('**/api/agent/status', (route) => {
		route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(fixtureAgentStatus())
		});
	});
}

